local config = {
  ui_story_5023_50230101_1_dialog_content = "So... Young man, maybe you should give this a second thought.",
  ui_story_5023_50230101_2_dialog_content = "Why? Is there something wrong with my application form?",
  ui_story_5023_50230101_3_dialog_content = "First of all, we've never used application forms of any kind.",
  ui_story_5023_50230101_4_dialog_content = "If the reason you want to join the Rediesel Wrench is for Azure...",
  ui_story_5023_50230101_5_dialog_content = "I advise you to try your luck at the Squirming Sandworm. She actually spends more time there than at the base.",
  ui_story_5023_50230101_6_dialog_content = "Hey, Roy. I don't see you chat with anyone like this often. Having a leisurely day?",
  ui_story_5023_50230101_7_dialog_content = "... Miss Azure!",
  ui_story_5023_50230101_8_dialog_content = "This is?",
  ui_story_5023_50230101_9_dialog_content = "The 18th person this month who wants to join the Rediesel Wrench because of you.",
  ui_story_5023_50230101_10_dialog_content = "Don't you remember me? One night you broke in...",
  ui_story_5023_50230101_11_dialog_content = "You tied me to a chair and whipped me with a belt. You even put a collar and chain on me.",
  ui_story_5023_50230101_12_dialog_content = "You don't remember?",
  ui_story_5023_50230101_13_dialog_content = "Ah... You're that one from the Blue Lion Guild...",
  ui_story_5023_50230101_14_dialog_content = "Mmm!",
  ui_story_5023_50230101_15_dialog_content = "Heh... what a sturdy body you've got. The belt broke...",
  ui_story_5023_50230101_16_dialog_content = "Ready to tell me where the Blue Lion Guild hid our cargo?",
  ui_story_5023_50230101_17_dialog_content = "... Bull! Your cargo? You looted our carriage, we just took back what's ours!",
  ui_story_5023_50230101_18_dialog_content = "What's yours is mine, and what's mine is mine. You got that?",
  ui_story_5023_50230101_19_dialog_content = "I... I have nothing to tell you. Make it quick.",
  ui_story_5023_50230101_20_dialog_content = "I don't think you know the line between bravery and foolishness.",
  ui_story_5023_50230101_21_dialog_content = "Fine. Let's do this a different way then.",
  ui_story_5023_50230101_22_dialog_content = "<color=#e8d9bb>Click</color>",
  ui_story_5023_50230101_23_dialog_content = "Not bad, it really suits you.",
  ui_story_5023_50230101_24_dialog_content = "W-What is this?",
  ui_story_5023_50230101_25_dialog_content = "Someone asked me to buy this collar and chain from the Umbraton Market for them.",
  ui_story_5023_50230101_26_dialog_content = "I don't think this color suits the cutie it's meant for though, so I'm planning to get another one.",
  ui_story_5023_50230101_27_dialog_content = "How lovely it suits you so well! Otherwise it'd have gone to waste.",
  ui_story_5023_50230101_28_dialog_content = "... What are you going to do to me?",
  ui_story_5023_50230101_29_dialog_content = "Hmm... let's see. Why don't I chain you behind my car and take us on a ride around Umbraton?",
  ui_story_5023_50230101_30_dialog_content = "?!",
  ui_story_5023_50230101_31_dialog_content = "If that's not thrilling enough for you, I suppose I could drag you out to the country where the Eclipsites are...",
  ui_story_5023_50230101_32_dialog_content = "<color=#e8d9bb>Rustle...</color>",
  ui_story_5023_50230101_33_dialog_content = "Javier!",
  ui_story_5023_50230101_34_dialog_content = "Acer? I told you to stay hidden!",
  ui_story_5023_50230101_35_dialog_content = "Don't hurt my brother, please! *Sobbing*",
  ui_story_5023_50230101_36_dialog_content = "Javier... Please! Don't leave me behind!",
  ui_story_5023_50230101_37_dialog_content = "What's that sound?",
  ui_story_5023_50230101_38_dialog_content = "Didn't we just empty the warehouse? Could someone be snooping around investgating the Sight?",
  ui_story_5023_50230101_39_dialog_content = "H-How did they get in? ... What do we do? We're screwed if the boss finds out...",
  ui_story_5023_50230101_39X_dialog_content = "Out here in the sticks, no one's gonna know if we use an enhancing potion to transform into Eclipsites.",
  ui_story_5023_50230101_39X1_dialog_content = "C'mon, chug this down and let's get rid of 'em!",
  ui_story_5023_50230101_40_dialog_content = "... Looks like we've got trouble.",
  ui_story_5023_50230101_41_dialog_content = "Whatever, I guess my cover won't be blown if I just get rid of everyone.",
  ui_story_5023_50230101_42_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5023_50230101_43_dialog_content = "Graah!",
  ui_story_5023_50230101_44_dialog_content = "... Eclipsites? Why would Umbraton have—",
  ui_story_5023_50230101_45_dialog_content = "Ahh!",
  ui_story_5023_50230101_46_dialog_content = "Acer!",
  ui_story_5023_50230101_47_dialog_content = "<color=#e8d9bb>Swish... Boom!</color>",
  ui_story_5023_50230101_48_dialog_content = "Gaah...",
  ui_story_5023_50230101_49_dialog_content = "Acer!",
  ui_story_5023_50230101_50_dialog_content = "Javier! *Sobbing*",
  ui_story_5023_50230101_51_dialog_content = "Why can't you just listen to me? I told you to stay there!",
  ui_story_5023_50230101_52_dialog_content = "But... But... That grey-haired woman is so scary...",
  ui_story_5023_50230101_53_dialog_content = "Little girl, this scary grey-haired woman just saved your life.",
  ui_story_5023_50230101_54_dialog_content = "Don't come any closer!",
  ui_story_5023_50230101_55_dialog_content = "Heh, try stopping me.",
  ui_story_5023_50230101_56_dialog_content = "Please... Please don't hurt my brother!",
  ui_story_5023_50230101_57_dialog_content = "He needed money to treat my illness and ended up getting tricked into joining the Blue Lion Guild!",
  ui_story_5023_50230101_58_dialog_content = "Whenever he goes out working, I get locked in the warehouse by these scary-looking men...",
  ui_story_5023_50230101_59_dialog_content = "If he owes you anything, I promise I'll pay you back!",
  ui_story_5023_50230101_60_dialog_content = "Please... Don't hurt my brother...",
  ui_story_5023_50230101_61_dialog_content = "...",
  ui_story_5023_50230101_62_dialog_content = "Dirty tricks like using loved ones as hostages definitely aligns with the behavior expected of those third-rate guilds.",
  ui_story_5023_50230101_63_dialog_content = "Haven't you ever thought about what would happen to your sister if you died?",
  ui_story_5023_50230101_64_dialog_content = "... I...",
  ui_story_5023_50230101_65_dialog_content = "As opposed to acting brashly and charging headlong towards death, you should use your brain and figure out how to survive with her.",
  ui_story_5023_50230101_66_dialog_content = "Take this.",
  ui_story_5023_50230101_67_dialog_content = "What's in this bag?",
  ui_story_5023_50230101_68_dialog_content = "You can't even tell the sound of Nightium? How you idiotic Blue Lion Guild even make it in Umbraton is beyond me.",
  ui_story_5023_50230101_69_dialog_content = "It's my responsibility to ensure that the undeserved wealth in your hands goes where it belongs.",
  ui_story_5023_50230101_70_dialog_content = "Eventually, I will find what I'm looking for. When that time comes, I imagine your higher ups will come after you.",
  ui_story_5023_50230101_71_dialog_content = "It's not too late to run.",
  ui_story_5023_50230101_72_dialog_content = "Wait!",
  ui_story_5023_50230101_73_dialog_content = "... Why are you helping me?",
  ui_story_5023_50230101_74_dialog_content = "That's none of your business. Hurry up before I change my mind.",
  ui_story_5023_50230101_75_dialog_content = "<color=#e8d9bb>Bam!</color>",
  ui_story_5023_50230101_76_dialog_content = "An explosion! There was an explosion sound from the vicinity of the warehouse! Everyone go and take a look!",
  ui_story_5023_50230101_76X_dialog_content = "Nice... All the guards are drawn away. Not bad. I guess the kid's brighter than I thought.",
  ui_story_5023_50230101_77_dialog_content = "...",
  ui_story_5023_50230101_78_dialog_content = "Brother, huh...",
  ui_story_5023_50230101_79_dialog_content = "After that, Acer and I ran from place to place with the help of the money Azure gave me.",
  ui_story_5023_50230101_80_dialog_content = "Not long after, the Blue Lion Guild's conspiracy was exposed. The Shadowlord dealt with them, and we were finally free of our pursuers.",
  ui_story_5023_50230101_81_dialog_content = "I inquired about Miss Azure all over and learned about a bunch of heroic deeds she performed, which prompted me to want to join the Rediesel Wrench.",
  ui_story_5023_50230101_82_dialog_content = "Oh, so that's how you lost your wallet that time you went to Umbraton to buy a collar for Kafka's Franz?",
  ui_story_5023_50230101_83_dialog_content = "Why does it matter? I brought back the cargo and sold the intelligence for a good price, didn't I?",
  ui_story_5023_50230101_84_dialog_content = "You gave us a second opportunity at life, and I want to use it to repay your kindness.",
  ui_story_5023_50230101_85_dialog_content = "There's no need. I enjoy being alone, and I don't need gratitude from anyone.",
  ui_story_5023_50230101_86_dialog_content = "I need only my car, my gun and... maybe also a dog like Kafka's.",
  ui_story_5023_50230101_87_dialog_content = "Miss Azure, please accept me as your dog then!",
  ui_story_5023_50230101_88_dialog_content = "Hold on a second!",
  ui_story_5023_50230101_89_dialog_content = "Mind your language! We've got minors here!",
  ui_story_5023_50230101_90_dialog_content = "Hmm? Did he say something that's not suitable for minors?",
  ui_story_5023_50230101_91_dialog_content = "We're not kids anymore! Tell us what you mean, tell us what you mean!",
  ui_story_5023_50230101_92_dialog_content = "I heard him mention a dog... Is there a lost puppy?",
  ui_story_5023_50230101_93_dialog_content = "That's right. Before meeting Miss Azure, I was lost in life, just like a stray—",
  ui_story_5023_50230101_94_dialog_content = "Ahem!",
  ui_story_5023_50230101_95_dialog_content = "I told you to watch your language!",
  ui_story_5023_50230101_96_dialog_content = "You three! Go wash your hands, dinner is almost ready!",
  ui_story_5023_50230101_97_dialog_content = "Fine...",
  ui_story_5023_50230101_98_dialog_content = "What a straightforward young man. Interesting.",
  ui_story_5023_50230101_99_dialog_content = "Honestly, would you stop enticing young men left and right? When they can't find you, they become my problem.",
  ui_story_5023_50230101_100_dialog_content = "U-Um... Azure.",
  ui_story_5023_50230101_101_dialog_content = "Ah, it's Acer, isn't it? How are you doing? Feeling better?",
  ui_story_5023_50230101_102_dialog_content = "Yes. I'm okay now...",
  ui_story_5023_50230101_103_dialog_content = "Also, I learned many things whilst traveling with the Caravans and even saved some money helping the merchants...",
  ui_story_5023_50230101_104_dialog_content = "I-It's not enough to pay Miss Azure back the money you lent us, but I'll keep working hard!",
  ui_story_5023_50230101_105_dialog_content = "I never intended for you to... Never mind.",
  ui_story_5023_50230101_106_dialog_content = "At the end of the day, the Rediesel Wrench are just a group of uncultured bumpkins who get into brawls day after day.",
  ui_story_5023_50230101_107_dialog_content = "I think you'll be better off working as a waitress at the Squirming Sandworm. I know the owner well and I'll make sure he treats you right.",
  ui_story_5023_50230101_108_dialog_content = "As for your brother... I doubt he can handle a punch from Roy, but he's still got enough going for him to work security there.",
  ui_story_5023_50230101_109_dialog_content = "Once you master all their special mixed drinks, come open a tavern in our Oasis.",
  ui_story_5023_50230101_110_dialog_content = "Okay!",
  ui_story_5023_50230101_111_dialog_content = "You're really going to extreme lengths to get free drinks...",
  ui_story_5023_50230101_112_dialog_content = "I'm so hungry all of a sudden. What's for dinner?",
  ui_story_5023_50230101_113_dialog_content = "That was a very poor change of the subject.",
  ui_story_5023_50230101_114_dialog_content = "... I made steamed camel with desert onion.",
  ui_story_5023_50230201_1_dialog_content = "...",
  ui_story_5023_50230201_2_dialog_content = "... Excellent. He's not around. Now's the time.",
  ui_story_5023_50230201_3_dialog_content = "Azure?",
  ui_story_5023_50230201_4_dialog_content = "... Darn, I got caught!",
  ui_story_5023_50230201_5_dialog_content = "Why are you limping? Are you hurt?",
  ui_story_5023_50230201_6_dialog_content = "Shush... Quiet. Don't let Roy hear you.",
  ui_story_5023_50230201_7_dialog_content = "I'll never win an argument against him again if he finds out I got injured during an ambush.",
  ui_story_5023_50230201_8_dialog_content = "So you're... trying to sneak first aid supplies? I'll help you treat your wounds.",
  ui_story_5023_50230201_9_dialog_content = "Nah, they're just surface wounds. Plus you're heading out with Sinsa, aren't you?",
  ui_story_5023_50230201_10_dialog_content = "But I have liquor.",
  ui_story_5023_50230201_11_dialog_content = "... Deal.",
  ui_story_5023_50230201_12_dialog_content = "Well, it's not as bad as it appears. Most of the blood isn't yours, so you should be fine.",
  ui_story_5023_50230201_13_dialog_content = "I feel like I don't get as much care or attention from you these days. No longer love me?",
  ui_story_5023_50230201_14_dialog_content = "Did you hit your head by any chance? Because it seems like it. Maybe I should call Roy over to take a look.",
  ui_story_5023_50230201_15_dialog_content = "I was kidding. It was a joke!",
  ui_story_5023_50230201_16_dialog_content = "This is probably going to hurt a little. Bear with me.",
  ui_story_5023_50230201_17_dialog_content = "It's rare for you to fall into someone's trap.",
  ui_story_5023_50230201_18_dialog_content = "You should've seen how my opponents ended up.",
  ui_story_5023_50230201_19_dialog_content = "I believe vultures must be feeding on the remains of those lowly brats by now.",
  ui_story_5023_50230201_20_dialog_content = "The leader of the group claimed to be the survivor of a gang the Rediesel Wrench had eliminated in the past.",
  ui_story_5023_50230201_21_dialog_content = "Which gang?",
  ui_story_5023_50230201_22_dialog_content = "I asked the same question.",
  ui_story_5023_50230201_23_dialog_content = "We've gotten rid of so many gangs over the years, how are we supposed to remember all their names?",
  ui_story_5023_50230201_24_dialog_content = "Ah, but I remember Death Row. Your showdown with their leader was truly marvelous.",
  ui_story_5023_50230201_25_dialog_content = "That's about it... After all, it's been so many years.",
  ui_story_5023_50230201_26_dialog_content = "You should've seen the look on the bald guy's face when I told him I couldn't remember his gang at all, it was hilarious.",
  ui_story_5023_50230201_27_dialog_content = "However... Well. Because he knew us...",
  ui_story_5023_50230201_28_dialog_content = "He knew to lure me with information on Balsa survivors.",
  ui_story_5023_50230201_29_dialog_content = "I see. It's the one thing you'd go look into even knowing it could be a trap.",
  ui_story_5023_50230201_30_dialog_content = "There's no risk I'm unwilling to take if there's a chance it'll lead me to my brother.",
  ui_story_5023_50230201_31_dialog_content = "Shouldn't you be bringing someone with you at times like these?",
  ui_story_5023_50230201_32_dialog_content = "Ouch. Take it easy, would you?",
  ui_story_5023_50230201_33_dialog_content = "Your nursing skills haven't improved at all.",
  ui_story_5023_50230201_34_dialog_content = "You know I don't get injured often, just like you. I rarely have the opportunity to practice.",
  ui_story_5023_50230201_35_dialog_content = "Which is a good thing, by the way.",
  ui_story_5023_50230201_36_dialog_content = "Alright, I'm done.",
  ui_story_5023_50230201_37_dialog_content = "Here you go. Some good stuff from Jomu. I've been saving it just for you. On the rocks?",
  ui_story_5023_50230201_38_dialog_content = "Mmm... Beautiful!",
  ui_story_5023_50230201_39_dialog_content = "And sitting here, you get a panoramic view of the Oasis. I love it.",
  ui_story_5023_50230201_40_dialog_content = "Your shoulder is so comfy for leaning against.",
  ui_story_5023_50230201_41_dialog_content = "...",
  ui_story_5023_50230201_42_dialog_content = "I've gotta live, if only for these moments. To survive, and return.",
  ui_story_5023_50230201_43_dialog_content = "As long as you know that.",
  ui_story_5023_50230201_44_dialog_content = "Let's drink to our heart's content today!",
  ui_story_5023_50230201_45_dialog_content = "Hm... gladly.",
  ui_story_5023_50230301_1_dialog_content = "Teams are all set, ingredients and prizes... confirmed.",
  ui_story_5023_50230301_2_dialog_content = "Terrific. We've finally got something other than Jomu's Insect Protein Powder and random dolls this year as prizes.",
  ui_story_5023_50230301_3_dialog_content = "I wonder where Jomu is...",
  ui_story_5023_50230301_4_dialog_content = "Tiny One strung him up for taking up too much space in the warehouse, he's probably begging for mercy right now.",
  ui_story_5023_50230301_5_dialog_content = "Odi, you're back! Communication points for all the stages are set?",
  ui_story_5023_50230301_6_dialog_content = "Of course. Piece of cake.",
  ui_story_5023_50230301_7_dialog_content = "Do you have any idea how many stupid technical failures I have to deal with for all these idiots every day?",
  ui_story_5023_50230301_8_dialog_content = "More than half their issues are always fixed just by restarting! Quite frankly, it's their brains that need servicing—",
  ui_story_5023_50230301_9_dialog_content = "Err... I'm sorry. I talked too much.",
  ui_story_5023_50230301_10_dialog_content = "You're probably the only one busier than me in all of Rediesel Wrench.",
  ui_story_5023_50230301_11_dialog_content = "When Tiny One, Fleur and I all have our hands full, you're always the one we call for help...",
  ui_story_5023_50230301_12_dialog_content = "Haha, I'm no professional. I consider it a miracle I don't end up causing more trouble.",
  ui_story_5023_50230301_13_dialog_content = "There you are, Roy! Lepidoz's maintenance and testing is done.",
  ui_story_5023_50230301_14_dialog_content = "With so much rediesel in its tummy, Lepidoz should be able to follow our contestants to the end of the race without any problem.",
  ui_story_5023_50230301_15_dialog_content = "How handy Odi is also here! We have a few things to check with you regarding Lepidoz's radio communication settings...",
  ui_story_5023_50230301_16_dialog_content = "Roy!",
  ui_story_5023_50230301_17_dialog_content = "What's the matter, Leader?",
  ui_story_5023_50230301_17X_dialog_content = "Wow!",
  ui_story_5023_50230301_18_dialog_content = "Can you stop Zeta from adding so many weird details to my persona?!",
  ui_story_5023_50230301_19_dialog_content = "I don't mind being a berserker but why do I have to have to be \"thrice divorced\"?",
  ui_story_5023_50230301_20_dialog_content = "Er, back off a little first, will ya? The two of us old men standing with our faces so close together is gonna cause a scene.",
  ui_story_5023_50230301_21_dialog_content = "I'm not an old man!",
  ui_story_5023_50230301_22_dialog_content = "Sure, sure, give it a couple more years.",
  ui_story_5023_50230301_23_dialog_content = "Anyhow, it seems you're fine role-playing for Zeta, but you're not happy with your role.",
  ui_story_5023_50230301_24_dialog_content = "We don't all like going around answering to whatever Zeta calls us, unlike some people... Princess.",
  ui_story_5023_50230301_25_dialog_content = "Don't get me wrong! I find the princess role very challenging. Definitely one of the top three difficult characters to play.",
  ui_story_5023_50230301_26_dialog_content = "If you could change your persona, what would you pick? Don't tell me you'd use Shinnosuke...",
  ui_story_5023_50230301_27_dialog_content = "I haven't yet used those stories as bedtime tales for the kids yet.",
  ui_story_5023_50230301_28_dialog_content = "Zeta is easily influenced. If I do, it won't take long for her to change your role to a wandering traveler from the Far East wielding a demon blade.",
  ui_story_5023_50230301_29_dialog_content = "... You've read that series too?",
  ui_story_5023_50230301_30_dialog_content = "Are you kidding? All the strongholds know.",
  ui_story_5023_50230301_31_dialog_content = "You seem to have bought a bunch of copies to send to folks, then obsessively went after them asking about their favorite characters.",
  ui_story_5023_50230301_32_dialog_content = "That's right, but you make me sound so...",
  ui_story_5023_50230301_33_dialog_content = "\"I'll kill one thousand villains in this world to keep my sister safe for the rest of her life!\"",
  ui_story_5023_50230301_34_dialog_content = "You don't have to scream it!",
  ui_story_5023_50230301_35_dialog_content = "What's there to be embarassed about? Don't forget I've read all the poetry you wrote as a kid. Those were even more...",
  ui_story_5023_50230301_36_dialog_content = "By the way, I was cleaning the warehouse the other day and found a few more of those poetry collections.",
  ui_story_5023_50230301_37_dialog_content = "What?!",
  ui_story_5023_50230301_38_dialog_content = "Don't you dare show them to Azure! You have no idea how long she teased me about it afterwards!",
  ui_story_5023_50230301_39_dialog_content = "Ahahah. After all these years, you still don't know how to handle her.",
  ui_story_5023_50230301_40_dialog_content = "Hmm...",
  ui_story_5023_50230301_41_dialog_content = "This is an extremely rare opportunity. Do you wanna team up with Azure for the rally this year?",
  ui_story_5023_50230301_42_dialog_content = "Sometimes I really can't tell whether you're joking or not... is this what you call exposure therapy?",
  ui_story_5023_50230301_43_dialog_content = "But besides Azure, who else is more suited to show PlayerName the racing techniques of the Rediesel Wrench?",
  ui_story_5023_50230301_44_dialog_content = "... You have a point.",
  ui_story_5023_50230301_45_dialog_content = "But first, give me those poetry collections you found.",
  ui_story_5023_50230301_46_dialog_content = "Hmm... What shall I do?",
  ui_story_5023_50230301_47_dialog_content = "You know how things work in Rediesel Wrench: first come, first serve, finders, keepers.",
  ui_story_5023_50230301_48_dialog_content = "Unless, of course, you're ordering me as my leader... or if you can take them from me by force—",
  ui_story_5023_50230301_49_dialog_content = "... I'm not going to hold back then!",
  ui_story_5023_50230301_50_dialog_content = "Aww... how scary.",
  ui_story_5023_50230301_51_dialog_content = "Isn't PlayerName waiting for you? It's not nice to keep the guest waiting.",
  ui_story_5023_50230301_52_dialog_content = "It's too late to take back your words, Roy.",
  ui_story_5023_50230301_53_dialog_content = "Change my mind? Never! You have one minute. Take this notepad from me and the poems will be yours.",
  ui_story_5023_50230301_54_dialog_content = "Otherwise, give it some serious consideration joining the race with Azure.",
  ui_story_5023_50230301_55_dialog_content = "She's so fed up with my nagging. One of you might get through to her...",
  ui_story_5023_50230301_56_dialog_content = "Did you say something?",
  ui_story_5023_50230301_57_dialog_content = "Ahh... Nothing.",
  ui_story_5023_50230301_58_dialog_content = "You have 50 seconds left, Leader.",
  ui_story_5023_50230301_59_dialog_content = "That's cheating!",
  ui_story_5023_50230301_60_dialog_content = "Ouch... My whole body aches... Tiny One is ruthless...",
  ui_story_5023_50230301_61_dialog_content = "Hmm? A fight?",
  ui_story_5023_50230301_62_dialog_content = "Whoa! He dodged the boss's wrench and took off so fast!",
  ui_story_5023_50230301_63_dialog_content = "Roy is definitely not someone you want to mess with... What happened with them anyways?",
  ui_story_5023_50230301_64_dialog_content = "Huh? I wasn't paying attention. You better take care of your swollen head before you start butting into other people's business. Really, you never learn your lesson.",
  ui_story_5023_50230301_65_dialog_content = "I heard Zeta. And something about grabbing a notepad within one minute. ...That's it.",
  ui_story_5023_50230301_66_dialog_content = "I willing to bet one Tool Kit that in a battle of skill instead of stamina, Boss doesn't stand a chance.",
  ui_story_5023_50230301_67_dialog_content = "I'm out. I'm not stupid.",
  ui_story_5023_50230301_68_dialog_content = "Hmm. I've got a good headline for the Umbraton Daily.",
  ui_story_5023_50230301_69_dialog_content = "\"Conflict between Rediesel Wrench Leader and Senior Member over New Talent Training!\"",
  ui_story_5023_50230301_70_dialog_content = "I wonder how much Nightium people would pay to read that...",
  ui_story_5023_50230401_1_dialog_content = "Is there really no other option?",
  ui_story_5023_50230401_2_dialog_content = "Come on, trust me on this. Red Scorpion Pie is excellent.",
  ui_story_5023_50230401_3_dialog_content = "Since you're a VIP, the chef made it special just for you. Yours doesn't just have Deep Fried Flare Scorpion, it also includes a bonus Roasted Crimson Ring Snake.",
  ui_story_5023_50230401_4_dialog_content = "Is this meant to be encouragement?",
  ui_story_5023_50230401_5_dialog_content = "They both sound deathly to me!",
  ui_story_5023_50230401_6_dialog_content = "Don't be afraid! Pull off the head and butt and enjoy!",
  ui_story_5023_50230401_7_dialog_content = "The fittest survive. The strongest rule. This is how life in the desert works.",
  ui_story_5023_50230401_8_dialog_content = "You consume this pie with respect for the lives of the defeated creatures used to make it, their lives become part of your flesh and blood, and so life goes on.",
  ui_story_5023_50230401_9_dialog_content = "Your speech is very poetic and heavy-hitting, but I...",
  ui_story_5023_50230401_10_dialog_content = "Young man, how about some appetizer soup?",
  ui_story_5023_50230401_11_dialog_content = "Thank you!",
  ui_story_5023_50230401_12_dialog_content = "*Cough*... What in the world is this?",
  ui_story_5023_50230401_13_dialog_content = "Sandworm and Locust Soup!",
  ui_story_5023_50230401_14_dialog_content = "Wow, what a brutally straightforward name.",
  ui_story_5023_50230401_15_dialog_content = "Hang on, I've heard it before... was it in a book?",
  ui_story_5023_50230401_16_dialog_content = "Ha, you're pretty cultured!",
  ui_story_5023_50230401_17_dialog_content = "This is a famous desert delicacy. Apparently, some chefs from other regions have tried to reproduce it even when they couldn't get their hands on all the essential ingredients.",
  ui_story_5023_50230401_18_dialog_content = "\"Add smoked paprika and deep-fried locusts. Top it with a tablespoon of chili sauce...\"",
  ui_story_5023_50230401_19_dialog_content = "Do you happen to serve Sandstone Rice?",
  ui_story_5023_50230401_20_dialog_content = "How do you know the owner's special dish? It's not even on the menu!",
  ui_story_5023_50230401_21_dialog_content = "I guess he must truly enjoy our desert cuisine. Get him another bottle of camel milk.",
  ui_story_5023_50230401_22_dialog_content = "Is this restaurant owned by Uncle Johnny?",
  ui_story_5023_50230401_23_dialog_content = "Ohh? You've seen Rediesel Recipe as well?",
  ui_story_5023_50230401_24_dialog_content = "You can't be serious!",
  ui_story_5023_50230401_25_dialog_content = "I've been wanting to meet him ever since I read his book...",
  ui_story_5023_50230401_26_dialog_content = "Why didn't you say something earlier? Johnny's currently traveling the world searching for new inspirations.",
  ui_story_5023_50230401_27_dialog_content = "He's not coming back for the Blazing Rally.",
  ui_story_5023_50230401_28_dialog_content = "Johnny is one of the very few members here not so keen on racing.",
  ui_story_5023_50230401_29_dialog_content = "His heart and soul are filled with food.",
  ui_story_5023_50230401_30_dialog_content = "I bet he's currently lying in ambush outside an Eclipsite lair, on the hunt for tasty Eclipsites.",
  ui_story_5023_50230401_31_dialog_content = "Eclipsites are edible?!",
  ui_story_5023_50230401_32_dialog_content = "Now that I think about it, he did claim to be an Eclipsite meat taster in his book...",
  ui_story_5023_50230401_33_dialog_content = "It's a pity that you can't meet him this time. But food will... what was it again?",
  ui_story_5023_50230401_34_dialog_content = "Ah, right. Food will connect you two beyond time and space.",
  ui_story_5023_50230401_35_dialog_content = "I didn't just pull that out of my ass, by the way. It's what Johnny always says.",
  ui_story_5023_50230401_36_dialog_content = "He has plans to print it on the cover page of his Rediesel Recipe sequel.",
  ui_story_5023_50230401_37_dialog_content = "(Vice also loves to try out unusual ingredients... but her dishes are more like lethal weapons than actual food.)",
  ui_story_5023_50230401_38_dialog_content = "(But this is my opportunity to experience all the exciting things from the book!)",
  ui_story_5023_50230401_39_dialog_content = "(Worst scenario, my trip ends with me getting food poisoning the night before the race...)",
  ui_story_5023_50230401_40_dialog_content = "Okay! I'll eat!",
  ui_story_5023_50230401_41_dialog_content = "...",
  ui_story_5023_50230401_42_dialog_content = "(Ah! Somehow, I'm still alive. And...)",
  ui_story_5023_50230401_43_dialog_content = "... This... tastes pretty good.",
  ui_story_5023_50230401_44_dialog_content = "Yes! You like it!",
  ui_story_5023_50230401_45_dialog_content = "Yeah. The scorpion is so crispy outside and very tender and juicy inside. And the spicy and sour seasoning is to die for...",
  ui_story_5023_50230401_46_dialog_content = "... Listen to those fancy words! Do you get that all from the books you read?",
  ui_story_5023_50230401_47_dialog_content = "I know, right? Unlike us. We're only good at stuffing our faces and going, \"Damn, that's good stuff!\"",
  ui_story_5023_50230401_48_dialog_content = "Sigh. I wish Johnny could hear this for himself.",
  ui_story_5023_50230401_49_dialog_content = "... PlayerName.",
  ui_story_5023_50230401_50_dialog_content = "Yes?",
  ui_story_5023_50230401_51_dialog_content = "Would you be interested in trying and reviewing everything the restaurant has? That would really make Johnny happy.",
  ui_story_5023_50230401_52_dialog_content = "Err... I suggest we save some for the next time. My taste buds are at their limit for the day...",
  ui_story_5023_50230401_53_dialog_content = "The celebratory feast will take place at the very end of the race. You won't be able to get any seconds there.",
  ui_story_5023_50230401_54_dialog_content = "Is that so?",
  ui_story_5023_50230401_55_dialog_content = "(I'm a little disappointed but also slightly relieved...)",
  ui_story_5023_50230401_56_dialog_content = "Hey, don't worry! Roy is in charge of the celebration feast.",
  ui_story_5023_50230401_57_dialog_content = "It'll be another thrilling adventure for your taste buds, almost as thrilling as Johnny's dishes!",
  ui_story_5023_50230401_58_dialog_content = "Is eating always an adventure with Rediesel Wrench?",
  ui_story_5023_50230401_59_dialog_content = "Alright, you must be thirsty after all this talking.",
  ui_story_5023_50230401_60_dialog_content = "Drink this dragon's tongue rotten fruit juice and next we'll try out the secret menu!",
  ui_story_5023_50230401_61_dialog_content = "Um... Including sandstone rice?",
  ui_story_5023_50230401_62_dialog_content = "(It's going to be a long night...)",
  ui_story_5023_50230501_1_dialog_content = "Hmm... I... I can't see what's ahead...",
  ui_story_5023_50230501_2_dialog_content = "This voice... Zeta? What are all these clothes for?",
  ui_story_5023_50230501_3_dialog_content = "Woah!",
  ui_story_5023_50230501_4_dialog_content = "I must pick these up quickly.",
  ui_story_5023_50230501_5_dialog_content = "Emm... Zeta is doing laundry!",
  ui_story_5023_50230501_6_dialog_content = "All of these are mine!",
  ui_story_5023_50230501_7_dialog_content = "Jona, have you seen the clothes and hat I had hanging outside?",
  ui_story_5023_50230501_8_dialog_content = "No.",
  ui_story_5023_50230501_9_dialog_content = "Wait... I saw Zeta with a bunch of clothes earlier. She might've grabbed yours by accident.",
  ui_story_5023_50230501_10_dialog_content = "How, when she's half my size?",
  ui_story_5023_50230501_11_dialog_content = "I don't know about that. Some of your tops are pretty short. Love 'em, by the way.",
  ui_story_5023_50230501_12_dialog_content = "Heh... As much as I'd like to stay and listen to your flattery, I've really gotta go find Zeta.",
  ui_story_5023_50230501_13_dialog_content = "Go ahead. It's not like I'd be jealous or anything.",
  ui_story_5023_50230501_14_dialog_content = "Ugh... is this... supposed to be like this? Whatever!",
  ui_story_5023_50230501_15_dialog_content = "Ah! O-Oh no! Even I can tell it's not right...",
  ui_story_5023_50230501_16_dialog_content = "Maybe I'll wipe it? ...It's even worse now!",
  ui_story_5023_50230501_17_dialog_content = "According to Barbara, doing makeup is like drawing, but why...",
  ui_story_5023_50230501_18_dialog_content = "You really have to ask? Have you forgotten how terrible you are at drawing?",
  ui_story_5023_50230501_19_dialog_content = "<size=45>Aaaah!</size>",
  ui_story_5023_50230501_20_dialog_content = "A-Azure? What brings you here?!",
  ui_story_5023_50230501_21_dialog_content = "Stop right there. This is the heroine's secret base. If the devil's lackey forces her way in—",
  ui_story_5023_50230501_22_dialog_content = "<size=45>Let me finish!</size>",
  ui_story_5023_50230501_23_dialog_content = "Hmm? Shouldn't you look someone in the eyes when you speak to them?",
  ui_story_5023_50230501_24_dialog_content = "Um... u-uh... Ahem! *coughs* I have a cold and don't want to pass it to you...",
  ui_story_5023_50230501_25_dialog_content = "Oh my, a sudden illness, huh? Don't give me that, idiot don't get sick.",
  ui_story_5023_50230501_26_dialog_content = "Turn around for me.",
  ui_story_5023_50230501_27_dialog_content = "<size=45>H-Hold on! Can you promise that you won't laugh?</size>",
  ui_story_5023_50230501_28_dialog_content = "You know how hard it is to make me laugh.",
  ui_story_5023_50230501_29_dialog_content = "...",
  ui_story_5023_50230501_30_dialog_content = "Pfft...",
  ui_story_5023_50230501_31_dialog_content = "You promised you wouldn't laugh!",
  ui_story_5023_50230501_32_dialog_content = "I'm sorry, o great heroine.",
  ui_story_5023_50230501_33_dialog_content = "I expected it to be amusing but this exceeds all my expectations. How can anybody not laugh at this?",
  ui_story_5023_50230501_34_dialog_content = "You!",
  ui_story_5023_50230501_35_dialog_content = "Come. Wipe your face clean with this towel.",
  ui_story_5023_50230501_36_dialog_content = "...",
  ui_story_5023_50230501_37_dialog_content = "So tell me what's going on, why are you suddenly interested in makeup?",
  ui_story_5023_50230501_38_dialog_content = "...N-No reason!",
  ui_story_5023_50230501_39_dialog_content = "Well... You see, Barbara told me this would work as a magic charm that enhances the heroine's power!",
  ui_story_5023_50230501_40_dialog_content = "Yes! That's it!",
  ui_story_5023_50230501_41_dialog_content = "Oh? What kind of power are we talking about?",
  ui_story_5023_50230501_42_dialog_content = "Err... What kind? Umm...",
  ui_story_5023_50230501_43_dialog_content = "Well, it's certainly not intelligence. Hmm... could it be charismatic power?",
  ui_story_5023_50230501_44_dialog_content = "How'd you figure that out? Drat! The Absolute Zero Witch is even stronger than I thought...",
  ui_story_5023_50230501_45_dialog_content = "I just... I just <size=30>want to be mature and elegant like you...</size> ",
  ui_story_5023_50230501_46_dialog_content = "Huh? I can't hear you.",
  ui_story_5023_50230501_47_dialog_content = "<size=45>I said, I want to become mature and elegant just like you!</size>",
  ui_story_5023_50230501_48_dialog_content = "Because you're so strong and so pretty and you always draw people's attention without having to pull any tricks...",
  ui_story_5023_50230501_49_dialog_content = "Aww! Never thought I'd live to see you compliment me.",
  ui_story_5023_50230501_50_dialog_content = "Is that why you stole my clothes and hat?",
  ui_story_5023_50230501_51_dialog_content = "Yeah... But they're too big for me, I can't even wear them...",
  ui_story_5023_50230501_52_dialog_content = "This is a failed operation but Zeta will become a mature and glamorous woman one day! Even better than you!",
  ui_story_5023_50230501_53_dialog_content = "Oh, you... here, sit here.",
  ui_story_5023_50230501_54_dialog_content = "Huh?",
  ui_story_5023_50230501_55_dialog_content = "Women aren't mature and elegant because of the way they dress.",
  ui_story_5023_50230501_56_dialog_content = "Makeup and clothing are just surface-level ornaments.",
  ui_story_5023_50230501_57_dialog_content = "But you always have all the boys wrapped around your finger with your looks and your body!",
  ui_story_5023_50230501_58_dialog_content = "That... Well, I can't deny that, but let's just call it a harmless hobby of mine.",
  ui_story_5023_50230501_59_dialog_content = "I don't mind people commenting nicely on my figure.",
  ui_story_5023_50230501_60_dialog_content = "But I earn respect with my gun, car, combat skills and brains.",
  ui_story_5023_50230501_61_dialog_content = "Attention and idolization from others doesn't matter. You need to focus on doing what you're good at and what you can do.",
  ui_story_5023_50230501_62_dialog_content = "... Gosh, when have I also started lecturing the children...",
  ui_story_5023_50230501_63_dialog_content = "Zeta understands... but also not really.",
  ui_story_5023_50230501_64_dialog_content = "What kinds of things can I do?",
  ui_story_5023_50230501_65_dialog_content = "I'm only good for doing those small basic patrol tasks that Regina and the others can't be bothered with doing...",
  ui_story_5023_50230501_66_dialog_content = "Don't look down on the menial tasks that contribute to helping villagers expel Eclipsites.",
  ui_story_5023_50230501_67_dialog_content = "They're crucial to developing our relationship with all the villages and towns across the desert.",
  ui_story_5023_50230501_68_dialog_content = "I cry every time when I help Roy cut berry onions, and I can't even cut them well...",
  ui_story_5023_50230501_69_dialog_content = "But you help him make sure all the dishes taste good every time, don't you?",
  ui_story_5023_50230501_70_dialog_content = "Roy has thousands of recipes in his head but his sense of taste sucks. We would suffer a great deal without you.",
  ui_story_5023_50230501_71_dialog_content = "Sounds like there are a few things I can do pretty well after all! And I can do even better!",
  ui_story_5023_50230501_72_dialog_content = "I didn't know you could be this gentle and patient...",
  ui_story_5023_50230501_73_dialog_content = "Is there something you've forgotten?",
  ui_story_5023_50230501_74_dialog_content = "Huh?",
  ui_story_5023_50230501_75_dialog_content = "What's with this tiny mud footprint on my white jacket? Hmm?",
  ui_story_5023_50230501_76_dialog_content = "Err... This...",
  ui_story_5023_50230501_77_dialog_content = "Wash it again.",
  ui_story_5023_50230501_78_dialog_content = "N-No problem! My friends are very good at washing clothes!",
  ui_story_5023_50230501_79_dialog_content = "Don't just call it a day by tossing it into your machine and spin it with your Luminatics.",
  ui_story_5023_50230501_80_dialog_content = "Handwash only.",
  ui_story_5023_50230501_81_dialog_content = "Right. Now.",
  ui_story_5023_50230501_82_dialog_content = "*Sniff* Witches are scary after all...",
  ui_story_5023_50230601_1_dialog_content = "Twas a chilling, pitch black night...",
  ui_story_5023_50230601_2_dialog_content = "Perhaps because the wind was howling over the sand...",
  ui_story_5023_50230601_3_dialog_content = "Or perhaps it was the thought of hidden dangers lurking in the night that made me anxious.",
  ui_story_5023_50230601_4_dialog_content = "I tossed and turned restlessly in bed, insomnia refusing to let me fall into slumber.",
  ui_story_5023_50230601_5_dialog_content = "Whose idea was it to tell scary stories by the campfire?",
  ui_story_5023_50230601_6_dialog_content = "Shush! Listen!",
  ui_story_5023_50230601_7_dialog_content = "Just as I was drifting back and forth between my dreams and the waking world, I heard a voice.",
  ui_story_5023_50230601_8_dialog_content = "It was the voice of a woman, coming from right outside my room. It felt like whispers in the wind...",
  ui_story_5023_50230601_9_dialog_content = "Yet it also felt as if it was right next to me, breathing into my ear.",
  ui_story_5023_50230601_10_dialog_content = "Huh??",
  ui_story_5023_50230601_11_dialog_content = "I sat up at once. And what I saw in the dim moonlight...",
  ui_story_5023_50230601_12_dialog_content = "Stop! D-Don't go on...",
  ui_story_5023_50230601_13_dialog_content = "...was Rouge, Bently and Lompty sleeping soundly.",
  ui_story_5023_50230601_14_dialog_content = "... What the hell?! You call this— Ow!",
  ui_story_5023_50230601_15_dialog_content = "Don't interrupt Ruby when she's reading her amazing epic, Great Explorer Ruby's Adventures!",
  ui_story_5023_50230601_16_dialog_content = "My adrenaline was at its peak.",
  ui_story_5023_50230601_17_dialog_content = "Because I suddenly realized that although I intended to explore all of Astra...",
  ui_story_5023_50230601_18_dialog_content = "I hadn't even explored this place—our homeland!",
  ui_story_5023_50230601_19_dialog_content = "This creepy incident took place in the Oasis?! I... Fleur, wake up! Wake up!",
  ui_story_5023_50230601_20_dialog_content = "Aaaaaaaargh! Why does he sleep like a dead person?!",
  ui_story_5023_50230601_21_dialog_content = "Ahem... I don't care about boring stories like this. I'm not done with today's training yet, so I'll just—",
  ui_story_5023_50230601_22_dialog_content = "No leaving in the middle!",
  ui_story_5023_50230601_23_dialog_content = "So I decided to follow my heart and explorer instincts...",
  ui_story_5023_50230601_24_dialog_content = "I set out at once to see what this familiar base of ours could possibly be hiding.",
  ui_story_5023_50230601_25_dialog_content = "Aw, I didn't even know you went through all that!",
  ui_story_5023_50230601_26_dialog_content = "Looks like from now on I need keep one eye open in my sleep to provide her better protection.",
  ui_story_5023_50230601_27_dialog_content = "As I exited the door, the already scarce moonlight became obscured by dark clouds, enveloping the night in pitch black darkness.",
  ui_story_5023_50230601_28_dialog_content = "The wind, which had been howling all night, stopped. I could hear the sound of my own heart beating in the deathly stillness.",
  ui_story_5023_50230601_29_dialog_content = "Thump... Thump...",
  ui_story_5023_50230601_30_dialog_content = "And then suddenly! I heard it again!",
  ui_story_5023_50230601_31_dialog_content = "The voice was mumbling something, but it was barely distillable...",
  ui_story_5023_50230601_32_dialog_content = "Wait, this is a typo. It's supposed to say \"barely discernable\"... Anyways.",
  ui_story_5023_50230601_33_dialog_content = "It was too distant and barely discernable, I couldn't make out what it was saying at all.",
  ui_story_5023_50230601_34_dialog_content = "But in the absence of the wind, I could figure out where the sound was coming from...",
  ui_story_5023_50230601_35_dialog_content = "It was right above me! However...",
  ui_story_5023_50230601_36_dialog_content = "The room above me had always been empty!",
  ui_story_5023_50230601_37_dialog_content = "Ahh!",
  ui_story_5023_50230601_38_dialog_content = "Squeak!",
  ui_story_5023_50230601_39_dialog_content = "I-I-I thought Ruby's stories were your favorite, don't be a coward!",
  ui_story_5023_50230601_40_dialog_content = "It wasn't the story, it was your scream! It scared the living daylights out of me!",
  ui_story_5023_50230601_41_dialog_content = "Two emotions were clashing within me in that moment.",
  ui_story_5023_50230601_42_dialog_content = "The fear of the unknown sent a chill down my spine. Yet a flow of adrenaline shot through my body like electricity, all the way up to my brain!",
  ui_story_5023_50230601_43_dialog_content = "But the thrill of exploring the unknown soon suppressed the unease in my heart and helped me remain calm.",
  ui_story_5023_50230601_44_dialog_content = "I didn't hesitate and immediately started heading up the stairs.",
  ui_story_5023_50230601_45_dialog_content = "Ruby! Please wake me up if this happens again!",
  ui_story_5023_50230601_46_dialog_content = "This kind of thing is too dangerous for you to face all by yourself!",
  ui_story_5023_50230601_47_dialog_content = "I stopped outside the empty room for a long moment.",
  ui_story_5023_50230601_48_dialog_content = "The usually locked door was open just a crack, but there was no light inside.",
  ui_story_5023_50230601_49_dialog_content = "In the dark abbey... ahem.",
  ui_story_5023_50230601_50_dialog_content = "In the dark abyss, it felt like there was something watching me.",
  ui_story_5023_50230601_51_dialog_content = "For a split second, I wanted to just turn around and run away. However, Mr. Jim suddenly came to my mind.",
  ui_story_5023_50230601_52_dialog_content = "My idol, Mr. Jim the legendary explorer, would definitely overcome his fear and enter the dark room for an answer!",
  ui_story_5023_50230601_53_dialog_content = "And so, a warm stream of courage filled my heart and dispersed my fear.",
  ui_story_5023_50230601_54_dialog_content = "I put one hand on the handle, and just as I was about to enter, I heard the voice again.",
  ui_story_5023_50230601_55_dialog_content = "This time, it was loud and clear—",
  ui_story_5023_50230601_56_dialog_content = "\"Thank you for your company all these years. But I still feel so lonely at times...\"",
  ui_story_5023_50230601_57_dialog_content = "\"There are things I must do.\"",
  ui_story_5023_50230601_58_dialog_content = "W...What did it mean?",
  ui_story_5023_50230601_59_dialog_content = "I was about to get closer when I heard the sound of a gun being loaded.",
  ui_story_5023_50230601_60_dialog_content = "I sensed a bone-chilling desire to kill. It penetrated the darkness as well as my body like a sharp dagger.",
  ui_story_5023_50230601_61_dialog_content = "I moved backward step by step. Honestly, I can't recall how I returned to my bed.",
  ui_story_5023_50230601_62_dialog_content = "The next morning, I rushed to the room upstairs...",
  ui_story_5023_50230601_63_dialog_content = "It was empty.",
  ui_story_5023_50230601_64_dialog_content = "There are still lots of unknowns in this world waiting to be discovered...",
  ui_story_5023_50230601_65_dialog_content = "It must've been a phantom! I'm positive!",
  ui_story_5023_50230601_66_dialog_content = "If you'd stayed there a moment longer, that voice would have dragged you into the world of phantoms!",
  ui_story_5023_50230601_67_dialog_content = "The world of phantoms? Is that true, Ruby?",
  ui_story_5023_50230601_68_dialog_content = "I'm sorry, but your guess is as good as mine.",
  ui_story_5023_50230601_69_dialog_content = "It was an unsuccessful adventure. The truth remains hidden in the dense fog.",
  ui_story_5023_50230601_70_dialog_content = "I still have a lot of room to grow and improve as an explorer...",
  ui_story_5023_50230601_71_dialog_content = "If there is a world of phantoms, it would be interesting. Don't you guys think?",
  ui_story_5023_50230601_72_dialog_content = "Yes! I'll be by Ruby's side no matter what!",
  ui_story_5023_50230601_73_dialog_content = "Creak!",
  ui_story_5023_50230601_74_dialog_content = "Can I leave now...",
  ui_story_5023_50230601_75_dialog_content = "Achoo!",
  ui_story_5023_50230601_76_dialog_content = "Are you okay? Do you need a jacket?",
  ui_story_5023_50230601_77_dialog_content = "I'm not cold. It was just a random sneeze...",
  ui_story_5023_50230601_78_dialog_content = "I'd say it's because someone's gossiping about me, but you're talking about me in front of me, not behind my back... so it must be the dust.",
  ui_story_5023_50230601_79_dialog_content = "Are you sure you don't want a few days of rest before heading out again?",
  ui_story_5023_50230601_80_dialog_content = "I've kept your room untouched.",
  ui_story_5023_50230601_81_dialog_content = "No need. I got a message from a contact through the Courier Union regarding a batch of goods I've been looking for.",
  ui_story_5023_50230601_82_dialog_content = "Alright, then. Let me know if you need backup.",
  ui_story_5023_50230601_83_dialog_content = "Azure, take care of yourself. Eye of the Lynx, look after her.",
  ui_story_5023_50230601_84_dialog_content = "... Why are you talking to my gun?",
  ui_story_5023_50230601_85_dialog_content = "Hmm? Don't you speak to it often when you are alone?",
  ui_story_5023_50230601_86_dialog_content = "I'm off. I have a feeling that this is going to be a very fruitful trip.",
  ui_story_5023_50230601_87_dialog_content = "That would be perfect considering how much money we always need for repairs after the Blazing Rally...",
  ui_story_5023_50230601_88_dialog_content = "Happy hunting."
}
